// Config-Werte fuer Win-Back Agent
return [{
  json: {
    ac_api_url: 'https://neontrip35090.activehosted.com/api/3',
    days_cutoff: 90,
    days_inactive: 30,
    winback_tag_name: 'WINBACK',
    cooldown_days: 90,
    max_emails_per_run: 10,

    // Safety gates: do not send automated win-back emails to active projects
    // or sensitive B2B partner segments like Ladenbauer / Shopfitting.
    skip_open_deals_as_active_projects: true,
    skip_contacts_with_open_deal: true,
    excluded_segments: ['NT-1'],
    excluded_segment_keywords: [
      'ladenbauer',
      'ladenbau',
      'shopfitting',
      'shop fitting',
      'retail design',
      'innenausbau',
      'ladeneinrichtung',
      'laden einrichtung',
      'store design'
    ]
  }
}];

// Daten von den drei parallelen Branches
const config = $('Config').first().json;

// Lost Deals und offene Deals (ActiveCampaign status=0).
// Offene Deals werden als aktive Projekte behandelt und standardmaessig NICHT
// als Win-Back Kandidaten versendet.
const lostDealsRaw = $('Hole verlorene Deals').first().json.deals || [];
const openDealsRaw = $('Hole inaktive Deals').first().json.deals || [];

// WINBACK Tag Info (von Normalisiere Tag Info - immer vorhanden)
const tagInfo = $('Normalisiere Tag Info').first().json;
const tagId = tagInfo.tagId;

console.log(`WINBACK Tag ID: ${tagId}`);

// Kontakte die bereits den WINBACK-Tag haben
let taggedContactIds = new Set();
try {
  const taggedContactsRaw = $('Hole Kontakte mit WINBACK-Tag').first().json.contacts || [];
  taggedContactIds = new Set(taggedContactsRaw.map(c => String(c.id)));
  console.log(`Gefunden: ${taggedContactIds.size} Kontakte mit WINBACK-Tag`);
} catch (e) {
  console.log('Keine Kontakte mit WINBACK-Tag (Tag war neu)');
}

const now = new Date();
const cutoffDate = new Date();
const daysCutoff = config.days_cutoff || 90;
cutoffDate.setDate(now.getDate() - daysCutoff);

const daysInactive = config.days_inactive || 30;
const inactiveCutoff = new Date();
inactiveCutoff.setDate(now.getDate() - daysInactive);

const excludedSegments = new Set((config.excluded_segments || ['NT-1']).map(s => String(s).toUpperCase()));
const excludedKeywords = (config.excluded_segment_keywords || []).map(s => String(s).toLowerCase());
const skipOpenDeals = config.skip_open_deals_as_active_projects !== false;
const skipContactsWithOpenDeal = config.skip_contacts_with_open_deal !== false;

function contactIdOf(deal) {
  return String(deal && deal.contact ? deal.contact : '');
}

function flattenText(value, depth = 0) {
  if (value == null || depth > 3) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }
  if (Array.isArray(value)) {
    return value.map(v => flattenText(v, depth + 1)).join(' ');
  }
  if (typeof value === 'object') {
    return Object.values(value).map(v => flattenText(v, depth + 1)).join(' ');
  }
  return '';
}

function hasExcludedSegment(deal) {
  const haystack = flattenText(deal).toLowerCase();
  if (/\bnt[-_\s]?1\b/i.test(haystack)) return { skip: true, reason: 'segment NT-1' };
  for (const segment of excludedSegments) {
    if (haystack.includes(segment.toLowerCase())) {
      return { skip: true, reason: `segment ${segment}` };
    }
  }
  for (const keyword of excludedKeywords) {
    if (keyword && haystack.includes(keyword)) {
      return { skip: true, reason: `keyword ${keyword}` };
    }
  }
  return { skip: false, reason: null };
}

console.log(`Lost deals raw: ${lostDealsRaw.length}, Open deals raw: ${openDealsRaw.length}`);
console.log(`Cutoff date: ${cutoffDate.toISOString()} (Deals AELTER als ${daysCutoff} Tage)`);

const openContactIds = new Set(openDealsRaw.map(contactIdOf).filter(Boolean));
console.log(`Kontakte mit offenem AC-Deal/status=0: ${openContactIds.size}`);

// Filter verlorene Deals - NUR Deals AELTER als 90 Tage (Abkuehlzeit respektieren)
const filteredLost = lostDealsRaw.filter(d => {
  const cdate = new Date(d.cdate);
  return cdate < cutoffDate;
}).map(d => ({ ...d, source: 'lost' }));

console.log(`Verlorene Deals aelter als ${daysCutoff} Tage: ${filteredLost.length}`);

let filteredInactive = [];
if (!skipOpenDeals) {
  filteredInactive = openDealsRaw.filter(d => {
    const cdate = new Date(d.cdate);
    const mdate = new Date(d.mdate);
    return cdate < cutoffDate && mdate < inactiveCutoff;
  }).map(d => ({ ...d, source: 'inactive' }));
  console.log(`Inaktive offene Deals aelter als ${daysCutoff} Tage: ${filteredInactive.length}`);
} else {
  console.log(`Offene Deals/status=0 werden als aktive Projekte uebersprungen: ${openDealsRaw.length}`);
}

const timeFilteredDeals = [...filteredLost, ...filteredInactive];
console.log(`Nach Zeitfilter: ${timeFilteredDeals.length} Deals`);

// Deals ausschliessen deren Kontakt bereits den WINBACK-Tag hat
const dealsWithoutTag = timeFilteredDeals.filter(d => {
  const contactId = contactIdOf(d);
  const hasTag = taggedContactIds.has(contactId);
  if (hasTag) {
    console.log(`Skip: Kontakt ${contactId} hat bereits WINBACK-Tag`);
  }
  return !hasTag;
});

console.log(`Nach WINBACK-Tag Filter: ${dealsWithoutTag.length} Deals`);

// Kontakte mit offenem Deal/status=0 ausschliessen, damit laufende Projekte
// nicht automatisiert mit einer Win-Back Email angeschrieben werden.
const dealsWithoutActiveProject = dealsWithoutTag.filter(d => {
  const contactId = contactIdOf(d);
  const hasOpenDeal = skipContactsWithOpenDeal && d.source !== 'inactive' && openContactIds.has(contactId);
  if (hasOpenDeal) {
    console.log(`Skip: Kontakt ${contactId} hat ein offenes aktives Projekt/status=0`);
  }
  return !hasOpenDeal;
});

console.log(`Nach Active-Project Filter: ${dealsWithoutActiveProject.length} Deals`);

// Ladenbauer / NT-1 und verwandte Shopfitting-Signale ausschliessen.
const dealsWithoutExcludedSegments = dealsWithoutActiveProject.filter(d => {
  const result = hasExcludedSegment(d);
  if (result.skip) {
    console.log(`Skip: Deal ${d.id} ausgeschlossen wegen ${result.reason}`);
  }
  return !result.skip;
});

console.log(`Nach Segment-Ausnahme Filter: ${dealsWithoutExcludedSegments.length} Deals`);

// Deduplizieren
const uniqueDeals = [];
const seenIds = new Set();
for (const deal of dealsWithoutExcludedSegments) {
  if (!seenIds.has(deal.id)) {
    seenIds.add(deal.id);
    uniqueDeals.push(deal);
  }
}

const maxEmails = config.max_emails_per_run || 10;
console.log(`Nach Deduplizierung: ${uniqueDeals.length} Deals`);

if (uniqueDeals.length === 0) {
  console.log('Keine Deals zu verarbeiten');
  return [];
}

const limitedDeals = uniqueDeals.slice(0, maxEmails);
console.log(`Verarbeite ${limitedDeals.length} Deals (max: ${maxEmails})`);

return limitedDeals.map(deal => ({ json: { ...deal, winbackTagId: tagId } }));

// Deal kommt direkt vom splitInBatches
const deal = $('Für jeden Deal').first().json;
const response = $input.first().json;

// Falls noDeals Flag gesetzt ist, abbrechen
if (deal.noDeals) {
  return [];
}

// ActiveCampaign gibt contacts als Array zurück
const contactData = response.contacts?.[0] || response.contact || {};

const vorname = contactData.firstName || 'Kunde';
const nachname = contactData.lastName || '';
const email = contactData.email || '';
const firma = contactData.orgname || '';
const contactId = contactData.id || deal.contact; // Kontakt-ID für Tag-Setzen

// Deal Info
const dealTitle = deal.title || '';
const dealValue = deal.value || '';
const dealSource = deal.source; // 'lost' oder 'inactive'
const dealCdate = deal.cdate;
const daysSinceCreated = Math.floor((new Date() - new Date(dealCdate)) / (1000 * 60 * 60 * 24));

// Versuche Produkt aus Deal-Titel zu extrahieren
let produktInteresse = dealTitle;
if (dealTitle.includes('|')) {
  produktInteresse = dealTitle.split('|')[0].trim();
}

return [{
  json: {
    contact: {
      id: contactId, // WICHTIG: Für Tag-Setzen
      vorname,
      nachname,
      email,
      firma,
      fullName: `${vorname} ${nachname}`.trim()
    },
    deal: {
      id: deal.id,
      title: dealTitle,
      value: dealValue,
      source: dealSource,
      daysSinceCreated,
      produktInteresse
    },
    emailContext: {
      grund: dealSource === 'lost' ? 'Kunde hat abgesagt' : 'Keine Reaktion seit längerem',
      zeitraum: `${daysSinceCreated} Tagen`
    }
  }
}];

parameters.text:
=Schreibe eine freundliche, persönliche Win-Back Email für NEONTRIP (LED Neon Schilder).

KONTEXT:
- Kunde: {{ $json.contact.vorname }} {{ $json.contact.nachname }}
- Firma: {{ $json.contact.firma || 'nicht angegeben' }}
- Ursprüngliches Interesse: {{ $json.deal.produktInteresse }}
- Grund für Kontakt: {{ $json.emailContext.grund }}
- Letzte Aktivität: vor {{ $json.emailContext.zeitraum }}

ANWEISUNGEN:
1. Schreibe auf Deutsch, freundlich und nicht aufdringlich
2. Beginne mit 'Hallo {{ $json.contact.vorname }},'
3. Erwähne das ursprüngliche Interesse/Produkt
4. Frage ob sie noch Interesse haben oder ob sich ihre Wünsche geändert haben
5. Biete an, ein neues unverbindliches Angebot zu erstellen
6. Halte die Email kurz (max 5-6 Sätze)
7. KEINE Signatur am Ende (wird automatisch hinzugefügt)
8. Gib NUR den Email-Text zurück, keine Betreffzeile

parameters.jsCode:
const aiOutput = $input.first().json.output || $input.first().json.text || '';
const context = $('Bereite KI-Kontext vor').first().json;

// Email-Text formatieren (Zeilenumbrueche zu <br>)
const emailText = aiOutput.replace(/\n/g, '<br>');

// Neutraler Betreff ohne dynamische Deal-, Produkt- oder Kundennamen.
const betreff = 'Kurze Rückfrage von NEONTRIP';

return [{
  json: {
    to: context.contact.email,
    subject: betreff,
    body: emailText,
    contact: context.contact,
    deal: context.deal
  }
}];

const emailData = $('Parse Email + Signatur').first().json;

return [{
  json: {
    success: true,
    sentTo: emailData.to,
    subject: emailData.subject,
    dealId: emailData.deal.id,
    dealTitle: emailData.deal.title,
    timestamp: new Date().toISOString()
  }
}];

// Dieser Code normalisiert die Tag-Info
// Input kann von zwei Quellen kommen:
// 1. TRUE Branch: Hole Kontakte mit WINBACK-Tag (hat .contacts)
// 2. FALSE Branch: Erstelle WINBACK Tag (hat .tag)

const input = $input.first().json;
let tagId, tagName;

if (input.tag) {
  // FALSE Branch: Neu erstellter Tag
  tagId = input.tag.id;
  tagName = input.tag.tag;
  console.log(`Neuer Tag erstellt: ${tagName} (ID: ${tagId})`);
} else if (input.contacts !== undefined) {
  // TRUE Branch: Kam von 'Hole Kontakte mit WINBACK-Tag'
  // Tag-Info muss von 'Hole WINBACK-Tag Info' geholt werden
  const tagInfo = $('Hole WINBACK-Tag Info').first().json;
  if (tagInfo.tags && tagInfo.tags.length > 0) {
    tagId = tagInfo.tags[0].id;
    tagName = tagInfo.tags[0].tag;
    console.log(`Existierender Tag aus WINBACK-Tag Info: ${tagName} (ID: ${tagId})`);
  } else {
    throw new Error('Tag nicht gefunden in Hole WINBACK-Tag Info');
  }
} else if (input.tags && input.tags.length > 0) {
  // Direkter Input mit tags Array
  tagId = input.tags[0].id;
  tagName = input.tags[0].tag;
  console.log(`Existierender Tag: ${tagName} (ID: ${tagId})`);
} else {
  throw new Error('Kein Tag gefunden oder erstellt! Input: ' + JSON.stringify(Object.keys(input)));
}

return [{
  json: {
    tagId: tagId,
    tagName: tagName,
    tags: [{ id: tagId, tag: tagName }]
  }
}];
